// === CLEAN DATA: INTERNAL ===
function cleanDate(v) {
  if (v === undefined || v === null) return '';
  let s = String(v).trim();
  if (/^\d{4,6}$/.test(s) && Number(s) > 30000) {            // serial date Excel/Sheets
    const d = new Date(Math.round((Number(s) - 25569) * 86400 * 1000));
    return d.toISOString().slice(0, 10);
  }
  s = s.split(' ')[0].split('T')[0];
  let m = s.match(/^(\d{4})[\/\-.](\d{1,2})[\/\-.](\d{1,2})$/);   // YYYY-MM-DD
  if (m) return `${m[1]}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`;
  m = s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})$/);       // DD/MM/YYYY
  if (m) return `${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`;
  const d = new Date(v);
  return isNaN(d) ? '' : d.toISOString().slice(0, 10);
}
function cleanAmount(v) {
  if (v === undefined || v === null) return '';
  let s = String(v).trim().replace(/[.,]\d{1,2}$/, '');         // buang desimal (,00 / .00)
  return s.replace(/\D/g, '');                                   // buang semua non-angka (Rp, titik, koma, spasi)
}
function pick(obj, keywords) {
  const k = Object.keys(obj).find(key => keywords.some(w => key.toLowerCase().includes(w)));
  return k ? obj[k] : '';
}

return $input.all().map(item => {
  const row = item.json;
  const cleanD = cleanDate(pick(row, ['tanggal', 'date', 'tgl']));
  const cleanA = cleanAmount(pick(row, ['nominal', 'amount', 'jumlah']));
  return { json: {
    source: 'INTERNAL',
    keterangan: pick(row, ['keterangan', 'deskripsi', 'description', 'nama', 'klien']),
    cleanDate: cleanD,
    cleanAmount: cleanA,
    match_key: `${cleanD}_${cleanA}`
  }};
});

