// === LOGIKA REKONSILIASI ===
const all = $input.all().map(i => i.json);
const internal = all.filter(r => r.source === 'INTERNAL');
const bank = all.filter(r => r.source === 'BANK');

const count = (arr) => arr.reduce((m, r) => (m[r.match_key] = (m[r.match_key] || 0) + 1, m), {});
const bankPool = count(bank);
const internalPool = count(internal);

const out = [];

// Sisi Internal: cocok dengan Bank atau tidak
for (const r of internal) {
  if (bankPool[r.match_key] > 0) {
    bankPool[r.match_key]--;
    out.push({ json: { status: 'MATCHED', ...r } });
  } else {
    out.push({ json: { status: 'MISSING IN BANK', ...r } });
  }
}

// Sisi Bank: yang tidak ada pasangannya di Internal
for (const r of bank) {
  if (internalPool[r.match_key] > 0) {
    internalPool[r.match_key]--;   // sudah dihitung MATCHED dari sisi Internal
  } else {
    out.push({ json: { status: 'UNRECORDED INTERNAL', ...r } });
  }
}

return out;

// === SUSUN PESAN TELEGRAM (hanya selisih) ===
const rows = $input.all().map(i => i.json);
const missing = rows.filter(r => r.status === 'MISSING IN BANK');
const unrec = rows.filter(r => r.status === 'UNRECORDED INTERNAL');
const rp = n => 'Rp' + Number(n || 0).toLocaleString('id-ID');

const fmt = (list) => list.map((r, i) =>
  `${i + 1}. ${r.cleanDate} | ${rp(r.cleanAmount)} | ${r.keterangan || '-'}`).join('\n');

let text = `⚠️ LAPORAN REKONSILIASI - ADA SELISIH\n`;
text += `Total transaksi selisih: ${rows.length}\n`;
if (missing.length) text += `\n❌ MISSING IN BANK (${missing.length})\nAda di Internal, tidak ada di Bank:\n${fmt(missing)}\n`;
if (unrec.length) text += `\n📥 UNRECORDED INTERNAL (${unrec.length})\nAda di Bank, belum tercatat di Internal:\n${fmt(unrec)}\n`;

return [{ json: { text } }];
